mbr.copysrc:
     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0001                    */
     /* Bei Angabe eines Bereichs ist nur *FROMID zulässig.         */                    /* RADD */
     /* ----------------------------------------------------------- */

             PGM        PARM(&LI)

             DCL        VAR(&LI) TYPE(*CHAR) LEN(10)

             RMVMSGD MSGID(USR0001) MSGF(&LI/DUPMSGD )                                    /* RADD */
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0001) +
                MSGF(&LI/DUPMSGD ) +
                MSG(+
'Bei Angabe eines Bereichs ist nur *FROMID zulässig.'                 +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */                                                             /* RADD */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0002                    */
     /* Kombination *FROMID/*FROMMSGF nicht zulässig.               */                    /* RADD */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0002) MSGF(&LI/DUPMSGD )                                    /* RADD */
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0002) +
                MSGF(&LI/DUPMSGD ) +
                MSG(+
'Kombination *FROMID/*FROMMSGF nicht zulässig.'                       +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */                                                             /* RADD */
                                                                                          /* RADD */
     /* ----------------------------------------------------------- */                    /* RADD */
     /*   Cmd-ADDMSGD für Message-ID :   USR0003                    */                    /* RADD */
     /* Nachrichtenbeschreibung &3 in Datei &2/&1 ist bereits vorha */                    /* RADD */
     /* ----------------------------------------------------------- */                    /* RADD */
                                                                                          /* RADD */
             RMVMSGD MSGID(USR0003) MSGF(&LI/DUPMSGD )                                    /* RADD */
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */                        /* RADD */
                                                                                          /* RADD */
             ADDMSGD +
                MSGID(USR0003) +
                MSGF(&LI/DUPMSGD ) +
                MSG(+
'Nachrichtenbeschreibung &3 in Datei &2/&1 ist bereits vorhanden.'    +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR  10) +
                    (*CHAR  10) +
                    (*CHAR   7) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */                                                             /* RADD */
                                                                                          /* RADD */
     /* ----------------------------------------------------------- */                    /* RADD */
     /*   Cmd-ADDMSGD für Message-ID :   USR0004                    */                    /* RADD */
     /* Nachrichtenbeschreibung &3 in Datei &2/&1 erstellt.         */                    /* RADD */
     /* ----------------------------------------------------------- */                    /* RADD */
                                                                                          /* RADD */
             RMVMSGD MSGID(USR0004) MSGF(&LI/DUPMSGD )                                    /* RADD */
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */                        /* RADD */
                                                                                          /* RADD */
             ADDMSGD +
                MSGID(USR0004) +
                MSGF(&LI/DUPMSGD ) +
                MSG(+
'Nachrichtenbeschreibung &3 in Datei &2/&1 erstellt.'                 +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR  10) +
                    (*CHAR  10) +
                    (*CHAR   7) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */                                                             /* RADD */

             ENDPGM

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0001                    */
     /* Only *FROMID allowed if a range is specified.               */                    /* RADD */
     /* ----------------------------------------------------------- */

             PGM        PARM(&LI)

             DCL        VAR(&LI) TYPE(*CHAR) LEN(10)

             RMVMSGD MSGID(USR0001) MSGF(&LI/DUPMSGDE)                                    /* RADD */
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0001) +
                MSGF(&LI/DUPMSGDE) +
                MSG(+
'Only *FROMID allowed if a range is specified.'                       +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */                                                             /* RADD */

     /* ----------------------------------------------------------- */
     /*   Cmd-ADDMSGD für Message-ID :   USR0002                    */
     /* *FROMID/*FROMMSGF can not be specified at the same time.    */                    /* RADD */
     /* ----------------------------------------------------------- */

             RMVMSGD MSGID(USR0002) MSGF(&LI/DUPMSGDE)                                    /* RADD */
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0002) +
                MSGF(&LI/DUPMSGDE) +
                MSG(+
'*FROMID/*FROMMSGF can not be specified at the same time.'            +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */                                                             /* RADD */
                                                                                          /* RADD */
     /* ----------------------------------------------------------- */                    /* RADD */
     /*   Cmd-ADDMSGD für Message-ID :   USR0003                    */                    /* RADD */
     /* Message description &3 in file &2/&1 already exists.        */                    /* RADD */
     /* ----------------------------------------------------------- */                    /* RADD */
                                                                                          /* RADD */
             RMVMSGD MSGID(USR0003) MSGF(&LI/DUPMSGDE)                                    /* RADD */
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */                        /* RADD */
                                                                                          /* RADD */
             ADDMSGD +
                MSGID(USR0003) +
                MSGF(&LI/DUPMSGDE) +
                MSG(+
'Message description &3 in file &2/&1 already exists.'                +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR  10) +
                    (*CHAR  10) +
                    (*CHAR   7) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */                                                             /* RADD */
                                                                                          /* RADD */
     /* ----------------------------------------------------------- */                    /* RADD */
     /*   Cmd-ADDMSGD für Message-ID :   USR0004                    */                    /* RADD */
     /* Message description &3 in file &2/&1 created.               */                    /* RADD */
     /* ----------------------------------------------------------- */                    /* RADD */
                                                                                          /* RADD */
             RMVMSGD MSGID(USR0004) MSGF(&LI/DUPMSGDE)                                    /* RADD */
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */                        /* RADD */
                                                                                          /* RADD */
             ADDMSGD +
                MSGID(USR0004) +
                MSGF(&LI/DUPMSGDE) +
                MSG(+
'Message description &3 in file &2/&1 created.'                       +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR  10) +
                    (*CHAR  10) +
                    (*CHAR   7) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */                                                             /* RADD */

             ENDPGM

