/* =================================================================== */                 /* RADD */
/* >>PRE-COMPILER<<                                                    */                 /* RADD */
/*                                                                     */                 /* RADD */
/*   >>CRTCMD<< CRTCMD       CMD(&LI/&OB) +                            */                 /* RADD */
/*                           SRCFILE(&SL/&SF) +                        */                 /* RADD */
/*                           SRCMBR(&SM);                              */                 /* RADD */
/*                                                                     */                 /* RADD */
/*   >>COMPILE<<                                                       */                 /* RADD */
/*     >>PARM<< PGM(*LIBL/DUPMSGDC);                                   */                 /* RADD */
/*     >>PARM<< HLPPNLGRP(*LIBL/DUPMSGDPE);                            */                 /* RADD */
/*     >>PARM<< HLPID(DUPMSGD);                                        */                 /* RADD */
/*     >>PARM<< PRDLIB(&LI);                                           */                 /* RADD */
/*   >>END-COMPILE<<                                                   */                 /* RADD */
/*                                                                     */                 /* RADD */
/*   >>EXECUTE<<                                                       */                 /* RADD */
/*                                                                     */                 /* RADD */
/* >>END-PRE-COMPILER<<                                                */                 /* RADD */
/* =================================================================== */                 /* RADD */

             CMD        PROMPT('Duplicate Message Description')                           /* RADD */

             PARM       KWD(RANGE) +
                        TYPE(QMSGR) +
                        SNGVAL( +
                          (*ALL )) +
                        PROMPT('Range of message identifiers')                            /* RADD */

             PARM       KWD(FROMMSGF)                          +
                        TYPE(QUAL1)                            +
                        MIN(0)                                 +
                        PROMPT('From message file')                                       /* RADD */

             PARM       KWD(TOMSGID)                           +
                        TYPE(*CHAR)                            +
                        LEN(7)                                 +
                        EXPR(*YES)                             +
                        DFT(*FROMID)                           +
                        PROMPT('To message description')                                  /* RADD */

             PARM       KWD(TOMSGF)                            +
                        TYPE(QUAL2)                            +
                        PROMPT('To message file')                                         /* RADD */

             PARM       KWD(REPLACE)                           +
                        TYPE(*CHAR)                            +
                        LEN(1)                                 +
                        EXPR(*YES)                             +
                        DFT(*NO)                               +
                        RSTD(*YES)                             +
                        SPCVAL((*YES Y)                        +
                               (*NO  N))                       +
                        PROMPT('Replace message description')                             /* RADD */
                                                                                          /* RADD */
             PARM       KWD(MSGFLNG   ) TYPE(*CHAR)        +
                          LEN(10)                          +
                          CONSTANT(DUPMSGDE )                                             /* RADD */

QMSGR:       ELEM       TYPE(*NAME) +
                        LEN(7) +
                        DFT(*FIRST) +
                        SPCVAL( +
                          (*FIRST *FIRST )) +
                        FULL(*YES) +
                        EXPR(*YES) +
                        PROMPT('Lower value')                                             /* RADD */
             ELEM       TYPE(*NAME) +
                        LEN(7) +
                        DFT(*ONLY) +
                        SPCVAL( +
                          (*ONLY *ONLY  ) +
                          (*LAST *LAST  )) +
                        FULL(*YES) +
                        EXPR(*YES) +
                        PROMPT('Upper value')                                             /* RADD */

QUAL1:       QUAL       TYPE(*NAME) LEN(10)                    +
                        DFT(QCPFMSG)
             QUAL       TYPE(*NAME)                            +
                        LEN(10)                                +
                        DFT(*LIBL)                             +
                        SPCVAL((*LIBL   )                      +
                               (*CURLIB ))                     +
                        PROMPT('Library')                                                 /* RADD */

QUAL2:       QUAL       TYPE(*NAME)                            +
                        LEN(10)                                +
                        DFT(*FROMMSGF)                         +
                        SPCVAL(*FROMMSGF)
             QUAL       TYPE(*NAME)                            +
                        LEN(10)                                +
                        DFT(*LIBL)                             +
                        SPCVAL((*LIBL   )                      +
                               (*CURLIB ))                     +
                        PROMPT('Library')                                                 /* RADD */

/* =================================================================== */                 /* RADD */
/*                                                                     */                 /* RADD */
/*  Kurzdokumentation :                                                */                 /* RADD */
/*                                                                     */                 /* RADD */
/*  Bereich . . . : DUPMSGD                                            */                 /* RADD */
/*  Objekt  . . . : DUPMSGDC                                           */                 /* RADD */
/*  Beschreibung  : Tool: DUPMSGD    (Duplicate MessageD ) CPP         */                 /* RADD */
/*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */                 /* RADD */
/*  Datum . . . . : ?                                                  */                 /* RADD */
/*                                                                     */                 /* RADD */
/* =================================================================== */                 /* RADD */
/*                                                                     */                 /* RADD */
/*  This software is free software, you can redistribute it and/or     */                 /* RADD */
/*  modify it under the terms of the GNU General Public License (GPL)  */                 /* RADD */
/*  as published by the Free Software Foundation.                      */                 /* RADD */
/*                                                                     */                 /* RADD */
/*  See GNU General Public License for details.                        */                 /* RADD */
/*          http://www.opensource.org                                  */                 /* RADD */
/*          http://www.opensource.org/licenses/gpl-license.html        */                 /* RADD */
/*                                                                     */                 /* RADD */
/* =================================================================== */                 /* RADD */
/*  History:                                                           */                 /* RADD */
/*                                                                     */                 /* RADD */
/*  Datum       Name          Änderung                                 */                 /* RADD */
/*  ----------  ------------  ---------------------------------------  */                 /* RADD */
/*                                                                     */                 /* RADD */
/* =================================================================== */                 /* RADD */
/* >>PRE-COMPILER<<                                                    */                 /* RADD */
/*                                                                     */                 /* RADD */
/*   >>CRTCMD<< CRTBNDCL     PGM(&LI/&OB) +                            */                 /* RADD */
/*                           SRCFILE(&SL/&SF) +                        */                 /* RADD */
/*                           SRCMBR(&SM);                              */                 /* RADD */
/*                                                                     */                 /* RADD */
/*   >>COMPILE<<                                                       */                 /* RADD */
/*     >>PARM<< DBGVIEW(*LIST);                                        */                 /* RADD */
/*   >>END-COMPILE<<                                                   */                 /* RADD */
/*                                                                     */                 /* RADD */
/*   >>LINK<<                                                          */                 /* RADD */
/*     >>PARM<< DFTACTGRP(*NO);                                        */                 /* RADD */
/*     >>PARM<< ACTGRP(*NEW    );                                      */                 /* RADD */
/*   >>END-LINK<<                                                      */                 /* RADD */
/*                                                                     */                 /* RADD */
/*   >>EXECUTE<<                                                       */                 /* RADD */
/*                                                                     */                 /* RADD */
/* >>END-PRE-COMPILER<<                                                */                 /* RADD */
/* =================================================================== */                 /* RADD */
             PGM        PARM(&RFROMID    +
                             &QFROMFILE  +
                             &TOID       +
                             &QTOFILE    +
                             &REPLACE    +
                             &I_MSGF     )                                                /* RADD */

/*  Parameter  */
             /*  Input      */
             DCL        VAR(&RFROMID     ) TYPE(*CHAR) LEN( 40  )                         /* RADD */
             DCL        VAR(&QFROMFILE   ) TYPE(*CHAR) LEN( 20  )                         /* RADD */
             DCL        VAR(&TOID        ) TYPE(*CHAR) LEN(  7  )                         /* RADD */
             DCL        VAR(&QTOFILE     ) TYPE(*CHAR) LEN( 20  )                         /* RADD */
             DCL        VAR(&REPLACE     ) TYPE(*CHAR) LEN(  1  )                         /* RADD */
             DCL        VAR(&I_MSGF      ) TYPE(*CHAR) LEN( 10  )                         /* RADD */

/* interne Felder       */                                                                /* RADD */
             DCL        VAR(&FROMIDLOW   ) TYPE(*CHAR) LEN(  7  )                         /* RADD */
             DCL        VAR(&FROMIDHIGH  ) TYPE(*CHAR) LEN(  7  )                         /* RADD */
             DCL        VAR(&FROMFILE    ) TYPE(*CHAR) LEN( 10  )                         /* RADD */
             DCL        VAR(&FROMLIB     ) TYPE(*CHAR) LEN( 10  )                         /* RADD */
             DCL        VAR(&TOFILE      ) TYPE(*CHAR) LEN( 10  )                         /* RADD */
             DCL        VAR(&TOLIB       ) TYPE(*CHAR) LEN( 10  )                         /* RADD */
             DCL        VAR(&TOID_WRK    ) TYPE(*CHAR) LEN(  7  )                         /* RADD */
             DCL        VAR(&CMD         ) TYPE(*CHAR) LEN(2048 )                         /* RADD */
             DCL        VAR(&CMDLEN      ) TYPE(*DEC ) LEN(15 5 ) +
                                           VALUE(2048)                                    /* RADD */
                                                                                          /* RADD */
             DCL        VAR(&MSGID       ) TYPE(*CHAR) LEN(  7  )                         /* RADD */
             DCL        VAR(&RETRIEVEOP  ) TYPE(*CHAR) LEN(  7  )                         /* RADD */
             DCL        VAR(&ERRID       ) TYPE(*CHAR) LEN(  7  )                         /* RADD */
             DCL        VAR(&ERRDT       ) TYPE(*CHAR) LEN( 80  )                         /* RADD */
                                                                                          /* RADD */
/* Fehlerbehandlung     */                                                                /* RADD */
             DCL        VAR(&ERROR)      TYPE(*LGL) +
                          VALUE('0')                                                      /* RADD */
             DCL        VAR(&TRUE)       TYPE(*LGL) +
                          VALUE('1')                                                      /* RADD */
             DCL        VAR(&FALSE)      TYPE(*LGL) +
                          VALUE('0')                                                      /* RADD */
             DCL        VAR(&ERRMSGKEY)  TYPE(*CHAR) LEN(4)                               /* RADD */
                                                                                          /* RADD */
             DCL        VAR(&ERRMSGTYP)  TYPE(*CHAR) LEN(10) +
                          VALUE('*DIAG')                                                  /* RADD */
             DCL        VAR(&ERRNBRTYP)  TYPE(*CHAR) LEN(4) +
                          VALUE(X'00000001')                                              /* RADD */
             DCL        VAR(&ERRPGMMSGQ) TYPE(*CHAR) LEN(10) +
                          VALUE('*')                                                      /* RADD */
             DCL        VAR(&ERRSTKCTR)  TYPE(*CHAR) LEN(4) +
                          VALUE(X'00000001')                                              /* RADD */
             DCL        VAR(&ERRCODE  )  TYPE(*CHAR) LEN(4) +
                          VALUE(X'00000000')                                              /* RADD */
                                                                                          /* RADD */
/* Sende alle Fehler zur Error Handling Routine */                                        /* RADD */
             MONMSG     MSGID(CPF0000) EXEC(GOTO CMDLBL(ERROR))                           /* RADD */
                                                                                          /* RADD */
             CHGVAR     VAR(&ERROR    ) VALUE(&FALSE)                                     /* RADD */
                                                                                          /* RADD */
 /* -------------------------------------------------------------- */                     /* RADD */
 /*  Los geht's                                                    */                     /* RADD */
 /* -------------------------------------------------------------- */                     /* RADD */
                                                                                          /* RADD */
/* ---------------------------- */                                                        /* RADD */
/* Ermitteln der VON und BIS    */                                                        /* RADD */
/* MSG-ID                       */                                                        /* RADD */
/* ---------------------------- */                                                        /* RADD */
             CHGVAR     VAR(&FROMIDLOW ) VALUE(%SST(&RFROMID  3 7))                       /* RADD */
             CHGVAR     VAR(&FROMIDHIGH) VALUE(%SST(&RFROMID 10 7))                       /* RADD */

/* ---------------------------- */
/* MSGF zerlegen in Lib         */
/* und File                     */
/* ---------------------------- */
             CHGVAR     VAR(&FROMLIB   ) VALUE(%SST(&QFROMFILE 11 10))                    /* RADD */
             CHGVAR     VAR(&FROMFILE  ) VALUE(%SST(&QFROMFILE  1 10))                    /* RADD */
             CHGVAR     VAR(&TOLIB     ) VALUE(%SST(&QTOFILE   11 10))                    /* RADD */
             CHGVAR     VAR(&TOFILE    ) VALUE(%SST(&QTOFILE    1 10))                    /* RADD */
                                                                                          /* RADD */
/* ---------------------------- */                                                        /* RADD */
/* Wenn VON-ID  =  *ALL         */                                                        /* RADD */
/* dann VON-ID  =  *FIRST       */                                                        /* RADD */
/* und  BIS-ID  =  *LAST        */                                                        /* RADD */
/* ---------------------------- */                                                        /* RADD */
               IF         COND(&FROMIDLOW *EQ '*ALL') THEN(DO)                            /* RADD */
                 CHGVAR     VAR(&FROMIDLOW ) VALUE('*FIRST')                              /* RADD */
                 CHGVAR     VAR(&FROMIDHIGH) VALUE('*LAST')                               /* RADD */
               ENDDO                                                                      /* RADD */
                                                                                          /* RADD */
/* ---------------------------- */                                                        /* RADD */
/* Prüfen der Sonderwerte       */                                                        /* RADD */
/* ---------------------------- */                                                        /* RADD */
             IF         COND(&FROMIDHIGH *NE '*ONLY'     +
                        *AND &TOID       *NE '*FROMID')  THEN(DO)                         /* RADD */
               SNDPGMMSG  MSGID(USR0001) MSGF(&I_MSGF) +
                          TOPGMQ(*PRV (*PGMBDY)) +
                          MSGTYPE(*ESCAPE)                                                /* RADD */
               GOTO       CMDLBL(ERROR)                                                   /* RADD */
             ENDDO                                                                        /* RADD */
                                                                                          /* RADD */
             IF         COND(&TOID   *EQ '*FROMID'    +
                        *AND &TOFILE *EQ '*FROMMSGF') THEN(DO)                            /* RADD */
               SNDPGMMSG  MSGID(USR0002) MSGF(&I_MSGF) +
                          TOPGMQ(*PRV (*PGMBDY)) +
                          MSGTYPE(*ESCAPE)                                                /* RADD */
               GOTO       CMDLBL(ERROR)                                                   /* RADD */
             ENDDO                                                                        /* RADD */
                                                                                          /* RADD */
/* ---------------------------- */                                                        /* RADD */
/* Ersetzen der Sonderwerte     */                                                        /* RADD */
/* ---------------------------- */                                                        /* RADD */
                                                                                          /* RADD */
/* ... Ersetzen *FIRST      */                                                            /* RADD */
/*     durch Msg-ID         */                                                            /* RADD */
             IF         COND(&FROMIDLOW *EQ '*FIRST') THEN(DO)                            /* RADD */
               CHGVAR     VAR(&MSGID     ) VALUE('       ')                               /* RADD */
               CHGVAR     VAR(&RETRIEVEOP) VALUE('*FIRST ')                               /* RADD */
               CALL       PGM(DUPMSGDR2) PARM(&FROMLIB    +
                                              &FROMFILE   +
                                              &MSGID      +
                                              &RETRIEVEOP +
                                              &FROMIDLOW  +
                                              &ERRID      +
                                              &ERRDT      )                               /* RADD */
             ENDDO                                                                        /* RADD */
                                                                                          /* RADD */
/* ... Ersetzen "von-ID"    */                                                            /* RADD */
/*     durch gültige Msg-ID */                                                            /* RADD */
             IF         COND(&FROMIDLOW *NE '       ') THEN(DO)                           /* RADD */
               RTVMSG     MSGID(&FROMIDLOW) MSGF(&FROMLIB/&FROMFILE)                      /* RADD */
               MONMSG     MSGID(CPF2419) EXEC(DO)                                         /* RADD */
                 CHGVAR     VAR(&MSGID     ) VALUE(&FROMIDLOW)                            /* RADD */
                 CHGVAR     VAR(&RETRIEVEOP) VALUE('*NEXT  ')                             /* RADD */
                 CALL       PGM(DUPMSGDR2) PARM(&FROMLIB    +
                                                &FROMFILE   +
                                                &MSGID      +
                                                &RETRIEVEOP +
                                                &FROMIDLOW  +
                                                &ERRID      +
                                                &ERRDT      )                             /* RADD */
               ENDDO                                                                      /* RADD */
             ENDDO                                                                        /* RADD */
                                                                                          /* RADD */
/* ... Ersetzen *ONLY       */                                                            /* RADD */
/*     durch Msg-ID         */                                                            /* RADD */
             IF         COND(&FROMIDHIGH *EQ '*ONLY') THEN(DO)                            /* RADD */
               CHGVAR     VAR(&FROMIDHIGH) VALUE(&FROMIDLOW)                              /* RADD */
             ENDDO                                                                        /* RADD */
                                                                                          /* RADD */
/* ... Ersetzen *LAST       */                                                            /* RADD */
/*     durch Maximalwert    */                                                            /* RADD */
             IF         COND(&FROMIDHIGH *EQ '*LAST') THEN(DO)                            /* RADD */
               CHGVAR     VAR(&FROMIDHIGH) VALUE('ZZZFFFF')                               /* RADD */
             ENDDO                                                                        /* RADD */
                                                                                          /* RADD */
/* ... Ersetzen *FROMMSGF   */                                                            /* RADD */
             IF         COND(&TOFILE *EQ '*FROMMSGF') THEN(DO)                            /* RADD */
               CHGVAR     VAR(&TOFILE) VALUE(&FROMFILE)                                   /* RADD */
               CHGVAR     VAR(&TOLIB ) VALUE(&FROMLIB )                                   /* RADD */
             ENDDO                                                                        /* RADD */
                                                                                          /* RADD */
/* ---------------------------- */
/* prüfen, Msg Datei vorhanden  */
/* ---------------------------- */
             CHKOBJ     OBJ(&FROMLIB/&FROMFILE) OBJTYPE(*MSGF)                            /* RADD */
             CHKOBJ     OBJ(&TOLIB/&TOFILE    ) OBJTYPE(*MSGF)                            /* RADD */

/* ---------------------------- */
/* Lib durch qual. Namen        */
/* ersetzen                     */
/* ---------------------------- */
             RTVOBJD    OBJ(&FROMLIB/&FROMFILE) OBJTYPE(*MSGF) +
                          RTNLIB(&FROMLIB)                                                /* RADD */
             RTVOBJD    OBJ(&TOLIB/&TOFILE) OBJTYPE(*MSGF) +
                          RTNLIB(&TOLIB)                                                  /* RADD */

/* ---------------------------- */                                                        /* RADD */
/* Schleifenbeginn.             */                                                        /* RADD */
/* ---------------------------- */                                                        /* RADD */
LOOP:                                                                                     /* RADD */
                                                                                          /* RADD */
/* ... prüfen Schleifenende */                                                            /* RADD */
               IF         COND(&FROMIDLOW *NE ' ') THEN(DO)                               /* RADD */
                 IF         COND(&FROMIDLOW *GT &FROMIDHIGH) THEN(DO)                     /* RADD */
                   CHGVAR     VAR(&FROMIDLOW) VALUE(' ')                                  /* RADD */
                 ENDDO                                                                    /* RADD */
               ENDDO                                                                      /* RADD */
                                                                                          /* RADD */
               IF         COND(&FROMIDLOW *EQ ' ') THEN(DO)                               /* RADD */
                 GOTO ENDE                                                                /* RADD */
               ENDDO                                                                      /* RADD */
                                                                                          /* RADD */
               IF         COND(&TOID *EQ '*FROMID') THEN(DO)                              /* RADD */
                 CHGVAR     VAR(&TOID_WRK) VALUE(&FROMIDLOW)                              /* RADD */
               ENDDO                                                                      /* RADD */
               ELSE       CMD(DO)                                                         /* RADD */
                 CHGVAR     VAR(&TOID_WRK) VALUE(&TOID     )                              /* RADD */
               ENDDO                                                                      /* RADD */
                                                                                          /* RADD */
/* ... aufrufen             */                                                            /* RADD */
/*     Generierungsfunktion */                                                            /* RADD */
               CALL       PGM(DUPMSGDR1) PARM(&FROMLIB   +
                                              &FROMFILE  +
                                              &FROMIDLOW +
                                              &TOLIB     +
                                              &TOFILE    +
                                              &TOID_WRK  +
                                              &CMD       +
                                              &ERRID     +
                                              &ERRDT     )                                /* RADD */

/* ... prüfen auf Fehler    */                                                            /* RADD */
               IF         COND(&ERRID    *NE ' '     ) THEN(DO)                           /* RADD */
                 SNDPGMMSG  MSGID(&ERRID) MSGF(QCPFMSG) MSGDTA(&ERRDT) +
                            TOPGMQ(*PRV (*PGMBDY)) +
                            MSGTYPE(*ESCAPE)                                              /* RADD */
               ENDDO                                                                      /* RADD */
               ELSE       CMD(DO)                                                         /* RADD */
/* ... eintragen neue MsgD  */                                                            /* RADD */
                 IF         COND(&REPLACE *EQ 'Y') THEN(DO)                               /* RADD */
                   RMVMSGD    MSGID(&TOID_WRK) MSGF(&TOLIB/&TOFILE)                       /* RADD */
                   MONMSG     MSGID(CPF2419)    /* Msg-ID not found */                    /* RADD */
                 ENDDO                                                                    /* RADD */
                 CALL       PGM(QCMDEXC) PARM(&CMD     +
                                              &CMDLEN  )                                  /* RADD */
                 MONMSG     MSGID(CPF2412) EXEC(DO)                                       /* RADD */
                   SNDPGMMSG  MSGID(USR0003) MSGF(*LIBL/&I_MSGF) +
                              MSGDTA(&TOFILE *CAT +
                                     &TOLIB  *CAT +
                                     &TOID_WRK    ) +
                              TOPGMQ(*PRV (*PGMBDY)) +
                              MSGTYPE(*INFO)                                              /* RADD */
                   GOTO       CMDLBL(DUPERR)                                              /* RADD */
                 ENDDO                                                                    /* RADD */
                                                                                          /* RADD */
/* ... Fertigmeldung!       */                                                            /* RADD */
                   SNDPGMMSG  MSGID(USR0004) MSGF(*LIBL/&I_MSGF) +
                              MSGDTA(&TOFILE *CAT +
                                     &TOLIB  *CAT +
                                     &TOID_WRK    ) +
                            TOPGMQ(*PRV (*PGMBDY)) +
                            MSGTYPE(*INFO)                                                /* RADD */
 DUPERR:                                                                                  /* RADD */
               ENDDO                                                                      /* RADD */
                                                                                          /* RADD */
/* ... nächste MsgID        */                                                            /* RADD */
               CHGVAR     VAR(&MSGID     ) VALUE(&FROMIDLOW)                              /* RADD */
               CHGVAR     VAR(&RETRIEVEOP) VALUE('*NEXT  ')                               /* RADD */
               CALL       PGM(DUPMSGDR2) PARM(&FROMLIB    +
                                              &FROMFILE   +
                                              &MSGID      +
                                              &RETRIEVEOP +
                                              &FROMIDLOW  +
                                              &ERRID      +
                                              &ERRDT      )                               /* RADD */
                                                                                          /* RADD */
             GOTO       CMDLBL(LOOP)                                                      /* RADD */

 /* -------------------------------------------------------------- */                     /* RADD */
 /*  Programm beenden                                              */                     /* RADD */
 /* -------------------------------------------------------------- */                     /* RADD */
                                                                                          /* RADD */
ENDE:                                                                                     /* RADD */
             RCLRSC     LVL(*)                                                            /* RADD */
                                                                                          /* RADD */
/* -------------------------------------------------------------- */                      /* RADD */
/*    Fehler aufgetreten ?                                        */                      /* RADD */
/* -------------------------------------------------------------- */                      /* RADD */
                                                                                          /* RADD */
             IF         COND(&ERROR) THEN(DO)                                             /* RADD */
               /* Sende letzte *ESCAPE nochmals   */                                      /* RADD */
               CALL       PGM(QMHRSNEM) PARM(&ERRMSGKEY &ERRCODE)                         /* RADD */
             ENDDO                                                                        /* RADD */
                                                                                          /* RADD */
             RETURN                                                                       /* RADD */
                                                                                          /* RADD */
/* ---------------- */                                                                    /* RADD */
/* Nachrichten      */                                                                    /* RADD */
/* weiterreichen    */                                                                    /* RADD */
/* ---------------- */                                                                    /* RADD */
                                                                                          /* RADD */
 ERROR:                                                                                   /* RADD */
             IF         COND(&ERROR) THEN(GOTO CMDLBL(ENDE))                              /* RADD */
             ELSE       CHGVAR     VAR(&ERROR) VALUE(&TRUE)                               /* RADD */
                                                                                          /* RADD */
/* Verschiebe alle *DIAG Nachrichten zur             */                                   /* RADD */
/* vorangegangenen Programmwarteschlange             */                                   /* RADD */
             CALL       PGM(QMHMOVPM) PARM(&ERRMSGKEY &ERRMSGTYP +
                          &ERRNBRTYP &ERRPGMMSGQ &ERRSTKCTR &ERRCODE)                     /* RADD */
                                                                                          /* RADD */
             GOTO       CMDLBL(ENDE)                                                      /* RADD */

             ENDPGM
